import{_ as o,C as i,c as l,o as g,a3 as a,j as e,G as n,a as s}from"./chunks/framework.Dokpd4od.js";const S=JSON.parse('{"title":"Stages","description":"","frontmatter":{},"headers":[],"relativePath":"master/maintenance/configurations/stages.md","filePath":"master/maintenance/configurations/stages.md","lastUpdated":1791534257000}'),d={name:"master/maintenance/configurations/stages.md"};function u(m,t,c,h,p,_){const r=i("ImagePopup");return g(),l("div",null,[t[3]||(t[3]=a('<h1 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h1><p>A <strong>Stage</strong> represents a step in the lifecycle of a <a href="./../operations/maintenance-requests.html">Maintenance Request</a> — for example <em>New Request</em> → <em>In Progress</em> → <em>Repaired</em> → <em>Scrap</em>. Stages appear as a progress bar on top of every request so the technician can see exactly where the work is and move it forward with one click.</p><p><strong>Use Case:</strong> Customize the stages to match how your maintenance team actually works. You can add, rename, or reorder stages, and mark certain stages as <strong>Done</strong> so the system knows the request is closed.</p><blockquote><p><strong>In simple words:</strong> Stages are the <em>steps</em> a maintenance request goes through. The system ships with sensible defaults — change them only if your team uses different names.</p></blockquote><h2 id="default-stages" tabindex="-1">Default Stages <a class="header-anchor" href="#default-stages" aria-label="Permalink to &quot;Default Stages&quot;">​</a></h2><p>When the Maintenance plugin is installed, the following stages are created automatically:</p><table tabindex="0"><thead><tr><th>Order</th><th>Stage Name</th><th>Done?</th></tr></thead><tbody><tr><td>1</td><td>New Request</td><td>No</td></tr><tr><td>2</td><td>In Progress</td><td>No</td></tr><tr><td>3</td><td>Repaired</td><td>Yes</td></tr><tr><td>4</td><td>Scrap</td><td>Yes</td></tr></tbody></table><p>Requests in <strong>Done</strong> stages are treated as closed. For <strong>preventive recurring</strong> requests, moving to a Done stage also triggers the system to automatically create the <em>next</em> recurring request.</p><h2 id="steps-to-create-a-new-stage" tabindex="-1">Steps to Create a New Stage <a class="header-anchor" href="#steps-to-create-a-new-stage" aria-label="Permalink to &quot;Steps to Create a New Stage&quot;">​</a></h2>',9)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[s("Navigate to "),e("strong",null,[e("code",null,"Maintenance → Configurations → Stages")]),s(" as shown below:")],-1)),n(r,{src:"/images1/maintenance/stage_navigation.png",alt:"Stages Navigation"})]),e("li",null,[t[1]||(t[1]=a("<p>Click <strong>New Stage</strong> and fill in:</p><ul><li><strong><em>Name:</em></strong> The display name of the stage (e.g. <code>Waiting for Parts</code>, <code>Quality Check</code>). Must be unique.</li><li><strong><em>Done:</em></strong> Toggle <strong>ON</strong> if a request reaching this stage should be considered <strong>closed/complete</strong>. Leave <strong>OFF</strong> for in-progress stages.</li></ul>",2)),n(r,{src:"/images1/maintenance/stage_general_section.png",alt:"Stage General Section"})]),t[2]||(t[2]=e("li",null,[e("p",null,[e("strong",null,"Action Buttons:")]),e("ul",null,[e("li",null,[e("strong",null,"Create"),s(" – Save the new stage.")]),e("li",null,[e("strong",null,"Cancel"),s(" – Discard.")])])],-1))]),t[4]||(t[4]=a('<h2 id="list-view-—-reordering-actions" tabindex="-1">List View — Reordering &amp; Actions <a class="header-anchor" href="#list-view-—-reordering-actions" aria-label="Permalink to &quot;List View — Reordering &amp; Actions&quot;">​</a></h2><p>The <strong>Stages</strong> list view shows every stage with the following columns: <strong>Name</strong> and <strong>Done</strong>.</p><p>You can:</p><ul><li><strong>Reorder Stages:</strong> Drag-and-drop stages to change the order in which they appear on the request progress bar.</li><li><strong>Group by:</strong> Done status or Created date.</li><li><strong>Edit:</strong> Rename a stage or change its Done flag.</li><li><strong>Delete:</strong> Remove a stage. <em>Be careful</em> — deleting a stage that requests are using will fail.</li></ul>',4)),n(r,{src:"/images1/maintenance/stage_list_view.png",alt:"Stage List View"}),t[5]||(t[5]=a('<h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Stages give you:</p><ul><li>A clear visual workflow for every <a href="./../operations/maintenance-requests.html">Maintenance Request</a>.</li><li>Control over what &quot;done&quot; means for your team.</li><li>Automatic generation of the next request when a recurring preventive request is closed.</li></ul><blockquote><p><strong>Tip:</strong> Keep the number of stages small — 3 to 5 stages usually work best. More than that and the progress bar becomes hard to read.</p></blockquote><blockquote><p><strong>Next step:</strong> With stages, <a href="./teams.html">Teams</a>, and <a href="./categories.html">Categories</a> configured, you are ready to start creating <a href="./../operations/maintenance-requests.html">Maintenance Requests</a>.</p></blockquote>',5))])}const q=o(d,[["render",u]]);export{S as __pageData,q as default};
